#ifndef _MOXA_SNMP_HANDLE_ENTRY_GET_VALUE_C_
#define _MOXA_SNMP_HANDLE_ENTRY_GET_VALUE_C_

#include "moxa_snmp_handle_entry_get_value.h"

struct entryGetValueFunction __entryGetValueFunctionTable[MAX_ENTRY_GET_VALUE_TABLE] = {0x0};

/**
 * @brief generate iss table entry file name

 * @param[in]    entry       moxa snmp entry
 * @param[out]   fileName    fileName
 * @param[in]    fileNameLen fileNameLen

 * @returns      0 means success, others fail.
 */
int32_t getEntryValue_utilGeneFileNameForIssTableEntry( struct ies_auto_mibs_entry  *entry,
                                                        char                        *fileName,
                                                        int                          fileNameLen )
{
    char buf[MOXA_SNMP_MAX_FILE_NAME] = {0x0};

    snprintf(buf, sizeof(buf), "%s", entry->uri);
    // remove '/' in table uri
    for ( int i = 0; i < 8 /* max parsing count */ ; i++ )
    {
        char *tmp = moxaSnmpHandle_UtilStringStrchr(buf, strlen(buf), '/');
        if ( tmp == NULL )
        {
            break;
        }
        *tmp = '_';
    }
    snprintf(fileName, fileNameLen, MOXA_SNMP_PATH "%stbl", buf);
    return 0;
}

/**
 * @brief function body for get uri-scalar-type-entry

 * @param[in]    reqinfo     netsnmp register handle
 * @param[in]    request     netsnmp request
 * @param[in]    entry       moxa snmp entry
 * @param[in]    getType     MOXA_SNMP_CONFIG_URI / MOXA_SNMP_STATUS_URI
 * @param[in]    dataType    MOXA_SNMP_JSON_BOOLEAN
                             MOXA_SNMP_JSON_NUMBER
                             MOXA_SNMP_JSON_STRING
                             MOXA_SNMP_JSON_IPV4Addr
                             MOXA_SNMP_JSON_MACAddr

 * @returns      0 means success, others fail.
 */
int32_t getEntryValue_uriScalarEntry( netsnmp_agent_request_info    *reqinfo,
                                      netsnmp_request_info          *request,
                                      struct ies_auto_mibs_entry    *entry,
                                      int32_t                        getType,
                                      int32_t                        dataType )
{
    int32_t       ret                   = (-1);
    char          uriPath[IES_MAX_URI]  = {0x0};
    JSON_Value   *jsonVal               = NULL;
    char         *valStr                = NULL;
    oid           oidValue[MAX_OID_LEN] = {0x0};
    size_t        oidValueLen;
    char          jsonValBuf[MOXA_SNMP_MAX_FILE_BUFF] = {0x0};
    char         *jsonValStr            = NULL;
    int           len                   = 0;

    if ( getType == MOXA_SNMP_CONFIG_URI )
    {
        snprintf( uriPath, sizeof(uriPath), IES_URI_CONFIG_PATH("/%s"), entry->uri );
    }
    else
    if ( getType == MOXA_SNMP_STATUS_URI )
    {
        snprintf( uriPath, sizeof(uriPath), MOXA_SNMP_URI_STATUS_PATH("/%s"), entry->uri );
    }
    else
    {
        LibUtil_DbgTrace( kDbgFlgIssUriSNMP, "Error in %s line %d\n", __func__, __LINE__ );
        return (-1);
    }

    if ( dataType == MOXA_SNMP_JSON_BOOLEAN )
    {
        if ( moxaSnmpHandle_UtilCfgGetURIConfig(uriPath, &jsonVal) != 0 )
        {
            json_value_free(jsonVal);
            jsonVal = NULL;
            LibUtil_DbgTrace( kDbgFlgIssUriSNMP, "Error in %s line %d\n", __func__, __LINE__ );
            return (-1);
        }

        snprintf(jsonValBuf, sizeof(jsonValBuf), "%d",
            ( json_value_get_boolean(jsonVal) == 1 /* true */) ? 1 /* true */ : 2 /*  false */ );

        valStr = jsonValBuf;
        LibUtil_DbgTrace( kDbgFlgIssUriSNMP, "%s@%d valStr = (%s)\n", __func__, __LINE__, valStr );
    }
    else
    if ( dataType == MOXA_SNMP_JSON_NUMBER   || dataType == MOXA_SNMP_JSON_STRING ||
         dataType == MOXA_SNMP_JSON_IPV4Addr || dataType == MOXA_SNMP_JSON_MACAddr )
    {
        if ( moxaSnmpHandle_UtilCfgGetURIConfigString(uriPath, jsonValBuf, sizeof(jsonValBuf)) != 0 )
        {
            LibUtil_DbgTrace( kDbgFlgIssUriSNMP, "%% %s@%d : can't UtilCfgGetURIConfigString\n", __func__, __LINE__ );
            goto config_end;
        }
        valStr = jsonValBuf;
        if ( valStr[0] == '"')
        {
            valStr++;
        }
        len = strlen(valStr);
        len = len - 1;
        if ( valStr[len] == '"' )
        {
            valStr[len] = '\0';
        }
        LibUtil_DbgTrace( kDbgFlgIssUriSNMP, "%s@%d valStr = (%s)\n", __func__, __LINE__, valStr );
    }

    // add .0 for scalar entry
    memcpy( oidValue, entry->oid_list, entry->oid_len * sizeof(oid));
    oidValueLen = entry->oid_len + 1;

    if ( moxaSnmpHandle_UtilSnmpUpdateGetRequest( reqinfo, request, entry, valStr, oidValue, oidValueLen ) != 0 )
    {
        LibUtil_DbgTrace( kDbgFlgIssUriSNMP, "Error in %s line %d\n", __func__, __LINE__ );
        goto config_end;
    }

    ret = 0;

config_end:

    if ( jsonVal != NULL ) 
    {
        json_value_free(jsonVal);
        jsonVal = NULL;
    }
    return ret;
}

/**
 * @brief function body for get uri-scalar-type-config-entry
                            for boolean type only

 * @param[in]    reqinfo     netsnmp register handle
 * @param[in]    request     netsnmp request
 * @param[in]    entry       moxa snmp entry

 * @returns      0 means success, others fail.
 */
int32_t getEntryValue_uriScalarConfig_boolean( netsnmp_agent_request_info    *reqinfo,
                                               netsnmp_request_info          *request,
                                               struct ies_auto_mibs_entry    *entry   )
{
    return getEntryValue_uriScalarEntry(reqinfo, request, entry,
                MOXA_SNMP_CONFIG_URI, MOXA_SNMP_JSON_BOOLEAN);
}

