                               uint8_t *const aNamePtr,
                               uint32_t *const aLengthPtr)
{
    // Check if buf size is enough
    if (aBufSize < LIB_SYSTEM_DEF_MODEL_NAME_LEN) {
        SYSTEM_DEBUG("short buf size: %d, exiting.\n", aBufSize);
        return LIB_SYSTEM_RET_NO_ENOUGH_MEM;
