#define SYS_SRV_SHM_SIZE        sizeof(struct MoxaSystemInfo)

/* gProductInfo is not ready in app_moxa_system due to
   pre_run_product_info_api() will be called before
   main() in app_moxa_system and data in SHM is
   prepared in app_moxa_system. */
struct MoxaProductInfo     gProductInfo;
void prepare_product_info_api (void)
{
    // Attach shm segment
    int32_t ret = -1;
    char *ptr = NULL;
    struct MoxaSystemInfo *shm_ptr;
    ret = LibUtil_ShmOpen(kShmSrvBlkTypeSysSrv, &ptr);
    if (ret) {
        SYSTEM_DEBUG("Error: shm open failed.\n");
        return;
    }
    shm_ptr = (struct MoxaSystemInfo *) ptr;

    // Output
    memcpy(&gProductInfo, &shm_ptr->mProductInfo,
           sizeof(struct MoxaProductInfo));

    // Detach shm segment
    ret = LibUtil_ShmClose(ptr);
    if (ret) {
        SYSTEM_DEBUG("Error: shm close failed.\n");
        return;
    }
}

void (*pre_run_product_info_api)() = prepare_product_info_api;

void __attribute__((constructor)) constructor_product_info_api() {
    // programs which do not want to cache can overwrite the pointer to NULL (in caller's program)
    if (pre_run_product_info_api) {
        pre_run_product_info_api();
    }
}

