/*
 * @brief Get serial number of the system.
 *
 * @param[in]     aBufSize                  Buffer size of SN.
 * @param[out]    aSNPtr                    Serial number.
 * @param[out]    aLengthPtr                Length of SN.
 * @returns       LIB_SYSTEM_RET_SUCCESS
 *                LIB_SYSTEM_RET_SHM_ERROR
 *                LIB_SYSTEM_RET_NO_ENOUGH_MEM
 */
int32_t LibSystem_GetSerialNumber(const uint32_t aBufSize,
                                  uint8_t *const aSerialNumberPtr,
                                  uint32_t *const aLengthPtr)
{
    // Check if buf size is enough
    if (aBufSize < LIB_SYSTEM_DEF_DEV_SERIAL_NUM_LEN) {
        SYSTEM_DEBUG("short buf size: %d, exiting.\n", aBufSize);
        return LIB_SYSTEM_RET_NO_ENOUGH_MEM;
    }

    // Output
    memcpy(aSerialNumberPtr,
           gProductInfo.mSerialNumber,
           sizeof(uint8_t) * LIB_SYSTEM_DEF_DEV_SERIAL_NUM_LEN);
    *aLengthPtr = strlen(gProductInfo.mSerialNumber);
    return LIB_SYSTEM_RET_SUCCESS;
}

