int32_t getEntryValue_generalInfo_devicePortNumber( netsnmp_agent_request_info    *reqinfo,
                                                    netsnmp_request_info          *request,
                                                    struct ies_auto_mibs_entry    *entry   )
{
    char          valStr[IES_MAX_FILE_BUF] = {0x0};
    oid           oidValue[MAX_OID_LEN]    = {0x0};
    size_t        oidValueLen;
    uint32_t      maxPortNum = 0;

    if ( LibSystem_GetMaxPortNumInSystem(&maxPortNum) != LIB_SYSTEM_RET_SUCCESS )
    {
        LibUtil_DbgTrace( kDbgFlgIssUriSNMP, "%% %s@%d : can't GetMaxPortNumInSystem \n",
            __func__, __LINE__ );
        return (-1);
    }
    snprintf(valStr, sizeof(valStr), "%d", maxPortNum);

    // add .0 for scalar entry
    memcpy( oidValue, entry->oid_list, entry->oid_len * sizeof(oid));
    oidValueLen = entry->oid_len + 1;

    if ( moxaSnmpHandle_UtilSnmpUpdateGetRequest( reqinfo, request, entry, valStr, oidValue, oidValueLen ) != 0 )
    {
        LibUtil_DbgTrace( kDbgFlgIssUriSNMP, "%% %s@%d : can't UpdateGetRequest \n",
            __func__, __LINE__ );
        return (-1);
    }

    return 0;
}



