 * @returns      N/A
 */
void dumpDebugLog( char *debugFile )
{
    FILE *fp = NULL;
    char  buf[1024] = {0x0};
    fp = fopen(debugFile, "r");
    if ( fp != NULL )
    {
        while(!feof(fp))
        {
            buf[0] = '\0';
            if ( fgets(buf, sizeof(buf), fp) == NULL )
            {
                break;
            }
            printf("%s", buf);
        }
        fclose(fp);
    }
    return;
}


